import {
  type AuthIR,
  camel,
  type FieldIR,
  kebab,
  type ModelAllowed,
  type ModelIR,
  modelAccess,
  plural,
  type SpecIR,
  USER_MODEL,
} from "@smithable/core";
import { aggregatedLists } from "./formulas.js";

const HEADER =
  "// Generated by Smithable from smithable.yml and smithable.auth.yml. Do not edit: this file is overwritten on every change.\n";

type Expected = Record<
  "readOthers" | "readOwn" | "create" | "changeOthers" | "changeOwn" | "deleteOthers" | "deleteOwn",
  boolean
>;

/** What a user with `role` (or a visitor, for null) may do, as the spec says. */
function expected(access: ModelAllowed, role: string | null): Expected {
  const has = (op: keyof ModelAllowed) =>
    access[op].public || (role !== null && access[op].roles.includes(role));
  // A visitor who has not signed in owns nothing.
  const own = (op: keyof ModelAllowed) => role !== null && (has(op) || access[op].owner);
  const readOthers = has("read");
  const readOwn = own("read");
  // Changing or deleting a record needs reading it first.
  return {
    readOthers,
    readOwn,
    create: has("create"),
    changeOthers: readOthers && role !== null && access.write.roles.includes(role),
    changeOwn: readOwn && role !== null && own("write"),
    deleteOthers: readOthers && role !== null && access.delete.roles.includes(role),
    deleteOwn: readOwn && role !== null && own("delete"),
  };
}

/** A generated test value for a required field; `n` keeps unique values apart. */
function testValue(field: FieldIR, model: ModelIR): string {
  if (field.type.kind === "choice") return JSON.stringify(field.type.values[0]);
  if (field.type.kind === "relation") {
    return field.type.model === USER_MODEL
      ? "owner ?? stranger.id"
      : `insert${field.type.model}(owner).id`;
  }
  switch (field.type.name) {
    case "int":
      return "n";
    case "decimal":
      return "1.5";
    case "money":
      return "1000";
    case "bool":
      return "true";
    case "date":
      return '"2026-01-15"';
    case "datetime":
      return 'new Date("2026-01-15T10:00:00Z")';
    case "email":
      return `\`${camel(model.name)}\${n}@example.com\``;
    case "phone":
      return `\`+358 40 \${1000000 + n}\``;
    case "url":
      return `\`https://example.com/\${n}\``;
    default:
      return `\`${model.name} ${field.name} \${n}\``;
  }
}

/**
 * A Vitest file that proves the effective access for every model and role, through the
 * same data functions the app uses, against the test database.
 */
export function accessTestSource(ir: SpecIR, auth: AuthIR): string {
  const signedIn = auth.signIn !== "none";
  const roles: (string | null)[] = [...(signedIn ? auth.roles.map((r) => r.name) : []), null];
  const tables = ir.models.map((m) => camel(plural(m.name)));
  const helpers = ir.models.map((model) => {
    // Every stored field: required and unique ones get a value, the rest are left empty.
    const fields = model.fields.filter(
      (f) => !f.formula && !(f.type.kind === "relation" && f.type.many),
    );
    const entries = fields.map((f) => {
      const key = f.type.kind === "relation" ? `${f.name}Id` : f.name;
      // A required owner still needs a user when the test acts as a visitor (owner null).
      const value =
        f.name === model.ownedBy
          ? f.required
            ? "owner ?? stranger.id"
            : "owner"
          : f.required || f.unique
            ? testValue(f, model)
            : "null";
      return `${key}: ${value}`;
    });
    const usesOwner = entries.some((e) => /\bowner\b/.test(e));
    const usesN = entries.some((e) => /\bn\b/.test(e));
    const ownerColumn = signedIn && !model.ownedBy ? ", ownerId: owner" : "";
    return `function ${camel(model.name)}Values(${usesOwner ? "owner" : "_owner"}: string | null) {
${usesN ? "  const n = next();\n" : ""}  return { ${entries.join(", ")} } as const;
}

function insert${model.name}(owner: string | null) {
  return db
    .insert(${camel(plural(model.name))})
    .values({ ...${camel(model.name)}Values(owner)${ownerColumn} })
    .returning()
    .get();
}`;
  });
  const describes = ir.models.map((model) => {
    const access = modelAccess(model, auth);
    const data = `${camel(model.name)}Data`;
    const values = `${camel(model.name)}Values`;
    const tests = roles.map((role) => {
      const viewer = role === null ? "null" : `signedIn(${JSON.stringify(role)})`;
      const title = role === null ? "a visitor who has not signed in" : role;
      const own = role !== null;
      return `  test(${JSON.stringify(title)}, async () => {
    const viewer = ${viewer};
    const others = insert${model.name}(${signedIn ? "stranger.id" : "null"});
${own ? `    const own = insert${model.name}(viewer.id);\n` : ""}    expect({
      readOthers: await reads(${data}, viewer, others.id),
      readOwn: ${own ? `await reads(${data}, viewer, own.id)` : "false"},
      create: await can(() => ${data}.create(viewer, ${values}(${own ? "viewer.id" : "null"}))),
      changeOthers: await can(() => ${data}.update(viewer, others.id, ${values}(${own ? "viewer.id" : "null"}))),
      changeOwn: ${own ? `await can(() => ${data}.update(viewer, own.id, ${values}(viewer.id)))` : "false"},
      deleteOthers: await can(() => ${data}.remove(viewer, others.id)),
      deleteOwn: ${own ? `await can(() => ${data}.remove(viewer, own.id))` : "false"},
    }).toEqual({
${Object.entries(expected(access, role))
  .map(([k, v]) => `      ${k}: ${v},`)
  .join("\n")}
    });
  });`;
    });
    // A list is for the records themselves: related records it adds up stay out of it, since
    // some may not be the viewer's to read.
    const lists = aggregatedLists(model);
    const reader = roles.find((role) => role !== null && expected(access, role).readOwn);
    if (lists.length && reader)
      tests.push(`  test("a list carries no related records, only what they add up to", async () => {
    const viewer = signedIn(${JSON.stringify(reader)});
    insert${model.name}(viewer.id);
    for (const row of await ${data}.list(viewer)) expect(Object.keys(row)).not.toContain(${JSON.stringify(lists[0])});
  });`);
    return `describe(${JSON.stringify(model.name)}, () => {
${tests.join("\n\n")}
});`;
  });
  const imports = [
    ...ir.models.map((m) => `import { ${camel(m.name)}Data } from "./${kebab(m.name)}.server";`),
  ];
  return `${HEADER}// For every model and role: which records a user can read, create, change and delete.
// "Own" records are owned by the user; "others" by someone else.
import { describe, expect, test } from "vitest";
import { db } from "#/db";
import { ${[...tables, ...(signedIn ? ["user"] : [])].sort().join(", ")} } from "#/db/schema";
import { AccessDenied${signedIn ? ", type Viewer" : ""} } from "#/kit/access";
${imports.join("\n")}

let counter = 0;
const next = () => ++counter;
${
  signedIn
    ? `
/** A new signed-in user with the role. */
function signedIn(role: string): Viewer {
  const n = next();
  const viewer = { id: \`test-user-\${n}\`, name: \`Test \${role} \${n}\`, email: \`user\${n}@example.com\`, role };
  db.insert(user).values(viewer).run();
  return viewer;
}

/** Owns the records that are someone else's. */
const stranger = signedIn(${JSON.stringify(auth.defaultRole)});
`
    : ""
}
/** Whether the action is allowed; any other failure fails the test. */
async function can(action: () => unknown): Promise<boolean> {
  try {
    await action();
    return true;
  } catch (error) {
    if (error instanceof AccessDenied) return false;
    throw error;
  }
}

/** Whether the viewer can open the record and sees it in the list. */
async function reads(
  data: { get(viewer: never, id: number): Promise<unknown>; list(viewer: never): Promise<{ id: number }[]> },
  viewer: unknown,
  id: number,
): Promise<boolean> {
  const listed = await data.list(viewer as never).then(
    (rows) => rows.some((row) => row.id === id),
    (error) => {
      if (error instanceof AccessDenied) return false;
      throw error;
    },
  );
  return listed && (await data.get(viewer as never, id)) !== null;
}

${helpers.join("\n\n")}

${describes.join("\n\n")}
`;
}
